var a=64;var i=[{id:`cooking-064-01`,theoryId:64,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which herb is often best added near the end for a bright fresh aroma?`,ua:`Яку зелень часто краще додавати наприкінці для яскравого свіжого аромату?`},explanation:{en:`Delicate fresh leaves lose some volatile top notes during prolonged heating.`,ua:`Ніжне свіже листя втрачає частину летких ароматів за тривалого нагрівання.`},options:[{id:`a`,text:{en:`Fresh basil`,ua:`Свіжий базилік`}},{id:`b`,text:{en:`Whole dried bay leaf`,ua:`Цілий сушений лавровий лист`}},{id:`c`,text:{en:`Hard cinnamon stick`,ua:`Тверду паличку кориці`}}],answer:{optionIds:[`a`]}},{id:`cooking-064-02`,theoryId:64,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Dried herbs can always replace fresh herbs by equal weight without changing a dish.`,ua:`Сушені трави завжди можна замінювати свіжими в однаковій масі без змін у страві.`},explanation:{en:`Drying changes water content and aroma profile; adjust and taste.`,ua:`Сушіння змінює вміст води та ароматичний профіль; потрібне коригування.`},answer:{value:!1}},{id:`cooking-064-03`,theoryId:64,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the herb form to a useful practice.`,ua:`Поєднайте форму зелені з доречною практикою.`},explanation:{en:`Timing depends on the herb structure and desired aroma.`,ua:`Момент додавання залежить від будови трави й бажаного аромату.`},leftItems:[{id:`l1`,text:{en:`Fresh parsley`,ua:`Свіжа петрушка`}},{id:`l2`,text:{en:`Dried oregano`,ua:`Сушений орегано`}},{id:`l3`,text:{en:`Dried bay leaf`,ua:`Сушений лавровий лист`}}],rightItems:[{id:`r3`,text:{en:`Infuse then remove the leaf`,ua:`Настояти та вийняти листок`}},{id:`r2`,text:{en:`Hydrate during sauce simmering`,ua:`Дати відновити аромат під час томління соусу`}},{id:`r1`,text:{en:`Add at the end for green freshness`,ua:`Додати наприкінці для свіжого зеленого аромату`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-064-04`,theoryId:64,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A tomato sauce needs fresh basil aroma at service. What do you do?`,ua:`Томатному соусу потрібен аромат свіжого базиліку під час подачі. Що зробити?`},explanation:{en:`Late addition preserves fresh aromatic top notes.`,ua:`Пізнє додавання допомагає зберегти свіжі леткі аромати.`},options:[{id:`a`,text:{en:`Tear fresh basil in just before serving`,ua:`Додати порваний свіжий базилік безпосередньо перед подачею`}},{id:`b`,text:{en:`Boil fresh basil for two hours`,ua:`Кип’ятити свіжий базилік дві години`}},{id:`c`,text:{en:`Replace it with plain sugar`,ua:`Замінити його звичайним цукром`}}],answer:{optionIds:[`a`]}},{id:`cooking-064-05`,theoryId:64,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which herb-handling practice is poor?`,ua:`Яка практика роботи із зеленню невдала?`},explanation:{en:`Warm, wet storage accelerates deterioration and may create safety concerns.`,ua:`Тепле вологе зберігання прискорює псування та може створювати ризики.`},options:[{id:`a`,text:{en:`Dry washed leaves before storage`,ua:`Обсушувати вимите листя перед зберіганням`}},{id:`b`,text:{en:`Use fresh herbs promptly`,ua:`Використовувати свіжу зелень без довгого зволікання`}},{id:`c`,text:{en:`Keep chopped fresh herbs wet and warm for hours`,ua:`Тримати подрібнену зелень мокрою й теплою годинами`}}],answer:{optionIds:[`c`]}}];var r={theoryId:64,exercises:i};export{r as default,i as exercises,a as theoryId};